 /// hand-off is not via pickup point.\n  pickupPointCost        Decimal?          @default(0) @map(\"pickup_point_cost\") @db.Decimal(10, 2)\n  /// Per ТЗ: при courier_pickup оператор зазначає, чи від цього відправника\n  /// це єдина посилка чи їх 2+. Впливає на мінімальний тариф.\n  /// NULL коли collectionMethod ≠ courier_pickup.\n  isMultiParcelPickup    Boolean?          @map(\"is_multi_parcel_pickup\")\n  /// \"Пакет\" — сума готівки, яку клієнт передає одержувачу. Опціональна\n  /// послуга: введена сума додається в квитанцію окремим рядком (N).\n  parcelMoneyAmount      Decimal?          @map(\"parcel_money_amount\") @db.Decimal(10, 2)\n  /// Calculated fee = parcelMoneyAmount × parcelMoneyPercent / 100.\n  parcelMoneyCost        Decimal?          @default(0) @map(\"parcel_money_cost\") @db.Decimal(10, 2)\n  totalCost              Decimal?          @map(\"total_cost\") @db.Decimal(10, 2)\n  costCurrency           String            @default(\"EUR\") @map(\"cost_currency\")\n  npTtn                  String?           @map(\"np_ttn\")\n  npTrackingStatus       String?           @map(\"np_tracking_status\")\n  status                 ParcelStatus      @default(draft)\n  createdSource          CreatedSource     @default(worker) @map(\"created_source\")\n  createdById            String?           @map(\"created_by\") @db.Uuid\n  assignedCourierId      String?           @map(\"assigned_courier_id\") @db.Uuid\n  estimatedDeliveryStart DateTime?         @map(\"estimated_delivery_start\") @db.Timestamptz\n  estimatedDeliveryEnd   DateTime?         @map(\"estimated_delivery_end\") @db.Timestamptz\n  isPaid                 Boolean           @default(false) @map(\"is_paid\")\n  paidAt                 DateTime?         @map(\"paid_at\") @db.Timestamptz\n  /// SMS-рахунок надіслано платнику (Отримувачу або Відправнику — згідно `payer`).\n  /// Null = ще не надіслано.\n  invoiceSentToPayerAt   DateTime?         @map(\"invoice_sent_to_payer_at\") @db.Timestamptz\n  photos                 String[]          @default([])\n  // Collection (how the company receives the parcel from sender, EU→UA side)\n  collectionMethod       CollectionMethod? @map(\"collection_method\")\n  collectionPointId      String?           @map(\"collection_point_id\") @db.Uuid\n  collectionDate         DateTime?         @map(\"collection_date\") @db.Date // planned date\n  collectionAddress      String?           @map(\"collection_address\") // for courier_pickup\n  collectedAt            DateTime?         @map(\"collected_at\") @db.Timestamptz // actual timestamp\n  collectedById          String?           @map(\"collected_by\") @db.Uuid\n  // Route task status (for daily route sheet)\n  routeTaskStatus        String?           @map(\"route_task_status\") // pending/address_confirmed/in_navigator/completed/not_completed/rescheduled\n  routeTaskFailReason    String?           @map(\"route_task_fail_reason\")\n  routeTaskReschedDate   DateTime?         @map(\"route_task_reschedule_date\") @db.Date\n  // Soft delete\n  deletedAt              DateTime?         @map(\"deleted_at\") @db.Timestamptz\n  createdAt              DateTime          @default(now()) @map(\"created_at\") @db.Timestamptz\n  updatedAt              DateTime          @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz\n\n  // Relations\n  sender           Client                @relation(\"ParcelSender\", fields: [senderId], references: [id])\n  senderAddress    ClientAddress?        @relation(\"ParcelSenderAddress\", fields: [senderAddressId], references: [id])\n  receiver         Client                @relation(\"ParcelReceiver\", fields: [receiverId], references: [id])\n  receiverAddress  ClientAddress?        @relation(\"ParcelReceiverAddress\", fields: [receiverAddressId], references: [id])\n  trip             Trip?                 @relation(fields: [tripId], references: [id])\n  collectionPoint  CollectionPoint?      @relation(\"ParcelCollectionPoint\", fields: [collectionPointId], references: [id])\n  collectedBy      Profile?              @relation(\"ParcelCollectedBy\", fields: [collectedById], references: [id])\n  createdBy        Profile?              @relation(\"ParcelCreatedBy\", fields: [createdById], references: [id])\n  assignedCourier  Profile?              @relation(\"ParcelAssignedCourier\", fields: [assignedCourierId], references: [id])\n  places           ParcelPlace[]\n  statusHistory    ParcelStatusHistory[]\n  cashEntries      CashRegister[]\n  routeTasks       RouteTask[]\n  warehouseActions WarehouseInventory[]\n  npSyncLogs       NpSyncLog[]\n  claims           Claim[]\n\n  @@index([itn])\n  @@index([npTtn])\n  @@index([senderId])\n  @@index([receiverId])\n  @@index([tripId])\n  @@index([status])\n  @@index([assignedCourierId])\n  @@index([createdAt])\n  @@index([sequentialNumber])\n  @@index([tripId, shortNumber])\n  @@index([collectionPointId])\n  // Composite indexes for hot queries\n  @@index([deletedAt, createdAt(sort: Desc)])\n  @@index([direction, status])\n  @@index([tripId, status])\n  @@index([isPaid, direction])\n  @@map(\"parcels\")\n}\n\nmodel ParcelPlace {\n  id                 String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  parcelId           String    @map(\"parcel_id\") @db.Uuid\n  placeNumber        Int       @map(\"place_number\")\n  weight             Decimal?  @db.Decimal(8, 3)\n  length             Decimal?  @db.Decimal(8, 2)\n  width              Decimal?  @db.Decimal(8, 2)\n  height             Decimal?  @db.Decimal(8, 2)\n  volume             Decimal?  @db.Decimal(10, 4)\n  volumetricWeight   Decimal?  @map(\"volumetric_weight\") @db.Decimal(8, 3)\n  needsPackaging     Boolean   @default(false) @map(\"needs_packaging\")\n  packagingDone      Boolean   @default(false) @map(\"packaging_done\")\n  itnPlace           String?   @unique @map(\"itn_place\")\n  barcodeData        String?   @map(\"barcode_data\")\n  scannedAtWarehouse DateTime? @map(\"scanned_at_warehouse\") @db.Timestamptz\n  scannedById        String?   @map(\"scanned_by\") @db.Uuid\n  createdAt          DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz\n  updatedAt          DateTime  @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz\n\n  // Relations\n  parcel    Parcel   @relation(fields: [parcelId], references: [id], onDelete: Cascade)\n  scannedBy Profile? @relation(\"PlaceScannedBy\", fields: [scannedById], references: [id])\n\n  @@unique([parcelId, placeNumber])\n  @@index([parcelId])\n  @@map(\"parcel_places\")\n}\n\nmodel ParcelStatusHistory {\n  id          String       @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  parcelId    String       @map(\"parcel_id\") @db.Uuid\n  status      ParcelStatus\n  changedById String?      @map(\"changed_by\") @db.Uuid\n  changedAt   DateTime     @default(now()) @map(\"changed_at\") @db.Timestamptz\n  notes       String?\n  location    String?\n\n  // Relations\n  parcel    Parcel   @relation(fields: [parcelId], references: [id], onDelete: Cascade)\n  changedBy Profile? @relation(fields: [changedById], references: [id])\n\n  @@index([parcelId])\n  @@index([changedAt])\n  @@index([parcelId, changedAt(sort: Desc)])\n  @@map(\"parcel_status_history\")\n}\n\nmodel PricingConfig {\n  id                          String     @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  country                     Country\n  direction                   Direction\n  pricePerKg                  Decimal    @map(\"price_per_kg\") @db.Decimal(10, 2)\n  /// Per ТЗ §49/§50 — знижена ціна за кг коли населений пункт Отримувача\n  /// = Львів. NULL = винятку немає, діє звичайний pricePerKg.\n  lvivPricePerKg              Decimal?   @map(\"lviv_price_per_kg\") @db.Decimal(10, 2)\n  weightType                  WeightType @default(custom) @map(\"weight_type\")\n  /// Per ТЗ §8 — частка фактичної ваги при `weightType=custom`. 0..1.\n  /// Розрахункова вага коли об'ємна > фактичної:\n  ///   billable = factualFrac × фактична + (1 − factualFrac) × об'ємна\n  /// При factualFrac = 1.0 поведінка ідентична `actual` (max).\n  /// При factualFrac = 0.0 поведінка ідентична `volumetric` (max).\n  /// При factualFrac = 0.5 поведінка ідентична `average`.\n  weightCustomFactualFraction Decimal    @default(0.5) @map(\"weight_custom_factual_fraction\") @db.Decimal(4, 3)\n  insuranceThreshold          Decimal    @default(25.00) @map(\"insurance_threshold\") @db.Decimal(10, 2)\n  insuranceRate               Decimal    @default(0.01) @map(\"insurance_rate\") @db.Decimal(5, 4)\n  insuranceEnabled            Boolean    @default(true) @map(\"insurance_enabled\")\n  packagingEnabled            Boolean    @default(true) @map(\"packaging_enabled\")\n  packagingPrices             Json?      @map(\"packaging_prices\")\n  /// Sum charged per each (full or partial) 10 kg when packaging checkbox is on.\n  /// Replaces the legacy tier JSON in `packagingPrices`.\n  packagingPer10kg            Decimal    @default(0) @map(\"packaging_per_10kg\") @db.Decimal(10, 2)\n  /// Whole-percent rate applied to the \"Пакет\" amount (cash transferred by sender).\n  /// Per ТЗ §53 — це НИЖНІЙ tier: діє коли сума Пакета ≤ parcelMoneyThreshold.\n  /// 0 disables the option.\n  parcelMoneyPercent          Decimal    @default(0) @map(\"parcel_money_percent\") @db.Decimal(5, 2)\n  /// Per ТЗ §53 — ВЕРХНІЙ tier «Пакет%»: діє коли сума Пакета > parcelMoneyThreshold.\n  parcelMoneyPercentHigh      Decimal    @default(0) @map(\"parcel_money_percent_high\") @db.Decimal(5, 2)\n  /// Per ТЗ §53 — межа (EUR) між нижнім і верхнім tier «Пакет%». ≤ поріг → low, > поріг → high.\n  parcelMoneyThreshold        Decimal    @default(2000) @map(\"parcel_money_threshold\") @db.Decimal(10, 2)\n  /// Flat price for handing the parcel over at a collection point (per ТЗ).\n  /// \"Мінімальна вартість кожної посилки при самостійній доставці/отриманні\n  /// клієнтом посилки на Пункті збору\" — діє як поріг (max(weight×price, цей)).\n  pickupPointPrice            Decimal    @default(0) @map(\"pickup_point_price\") @db.Decimal(10, 2)\n  /// \"Адресна доставка\" — мінімальна вартість посилки при заїзді кур'єра\n  /// на адресу (одна посилка від відправника). Діє як поріг.\n  addressDeliveryPrice        Decimal    @default(0) @map(\"address_delivery_price\") @db.Decimal(10, 2)\n  /// ТЗ docx 29.06.26 «Тарифи»: окрема додаткова послуга «Доставка до порога\n  /// будинку». doorstepEnabled — чи пропонується для цього напрямку;\n  /// doorstepPrice — фіксована сума, яка АДИТИВНО додається до вартості\n  /// посилки коли Отримувач обрав адресну доставку (до порога). На відміну\n  /// від addressDeliveryPrice (поріг) — це надбавка зверху.\n  doorstepEnabled             Boolean    @default(false) @map(\"doorstep_enabled\")\n  doorstepPrice               Decimal    @default(0) @map(\"doorstep_price\") @db.Decimal(10, 2)\n  /// Per ТЗ: «При передачі двох і більше посилок з однієї локації на різні\n  /// адреси — мінімальна вартість посилки на кожну одну адресу». Поріг\n  /// діє коли в формі обрано \"Дві або більше посилок\" для courier_pickup.\n  minMultiPerAddress          Decimal    @default(0) @map(\"min_multi_per_address\") @db.Decimal(10, 2)\n  /// Per ТЗ: «При отриманні з України та передачі в Україну одномоментно\n  /// з однієї локації — мінімальна вартість посилки з/на кожну одну адресу».\n  /// Поріг діє коли відправник одночасно і отримує і відправляє з тієї ж\n  /// локації. Логіка детекції — на бекенді.\n  minBothDirections           Decimal    @default(0) @map(\"min_both_directions\") @db.Decimal(10, 2)\n  collectionDays              String[]   @map(\"collection_days\")\n  isActive                    Boolean    @default(true) @map(\"is_active\")\n  updatedById                 String?    @map(\"updated_by\") @db.Uuid\n  createdAt                   DateTime   @default(now()) @map(\"created_at\") @db.Timestamptz\n  updatedAt                   DateTime   @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz\n\n  // Relations\n  updatedBy Profile? @relation(\"PricingUpdatedBy\", fields: [updatedById], references: [id])\n\n  @@map(\"pricing_config\")\n}\n\nmodel CollectionPoint {\n  id           String    @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  name         String? // Optional display name, e.g. \"Amsterdam Centraal\"\n  country      Country\n  city         String\n  address      String\n  postalCode   String?   @map(\"postal_code\")\n  contactPhone String?   @map(\"contact_phone\")\n  workingHours String?   @map(\"working_hours\") // Human readable, e.g. \"10:00-19:00\"\n  workingDays  Weekday[] @default([]) @map(\"working_days\")\n  latitude     Decimal?  @db.Decimal(10, 7)\n  longitude    Decimal?  @db.Decimal(10, 7)\n  notes        String? // Instructions for clients\n  maxCapacity  Int?      @map(\"max_capacity\") // Optional cap per trip, null = unlimited\n  isActive     Boolean   @default(true) @map(\"is_active\")\n  createdAt    DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz\n  updatedAt    DateTime  @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz\n\n  parcels Parcel[] @relation(\"ParcelCollectionPoint\")\n\n  @@index([country])\n  @@index([isActive])\n  @@map(\"collection_points\")\n}\n\nmodel CashRegister {\n  id            String          @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  parcelId      String?         @map(\"parcel_id\") @db.Uuid\n  amount        Decimal         @db.Decimal(10, 2)\n  currency      String\n  paymentMethod PaymentMethod   @map(\"payment_method\")\n  paymentType   CashPaymentType @default(income) @map(\"payment_type\")\n  description   String?\n  receivedById  String          @map(\"received_by\") @db.Uuid\n  confirmed     Boolean         @default(false)\n  confirmedById String?         @map(\"confirmed_by\") @db.Uuid\n  confirmedAt   DateTime?       @map(\"confirmed_at\") @db.Timestamptz\n  createdAt     DateTime        @default(now()) @map(\"created_at\") @db.Timestamptz\n\n  // Relations\n  parcel      Parcel?  @relation(fields: [parcelId], references: [id])\n  receivedBy  Profile  @relation(\"CashReceivedBy\", fields: [receivedById], references: [id])\n  confirmedBy Profile? @relation(\"CashConfirmedBy\", fields: [confirmedById], references: [id])\n\n  @@index([parcelId])\n  @@index([receivedById])\n  @@index([createdAt])\n  @@map(\"cash_register\")\n}\n\nmodel RouteTask {\n  id                    String          @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  tripId                String          @map(\"trip_id\") @db.Uuid\n  parcelId              String?         @map(\"parcel_id\") @db.Uuid\n  taskType              RouteTaskType   @map(\"task_type\")\n  // ТЗ docx 08.08.26 (v12): taskDate NULL = адреса ще в ЗАГАЛЬНОМУ списку (не в листі).\n  taskDate              DateTime?       @map(\"task_date\") @db.Date\n  clientId              String?         @map(\"client_id\") @db.Uuid\n  addressId             String?         @map(\"address_id\") @db.Uuid\n  addressText           String?         @map(\"address_text\")\n  postalCode            String?         @map(\"postal_code\")\n  // ТЗ docx 08.08.26 (v12): довільна адреса, додана Водієм вручну (без посилки).\n  manualName            String?         @map(\"manual_name\")\n  manualPhone           String?         @map(\"manual_phone\")\n  manualDirection       String?         @map(\"manual_direction\")\n  manualCity            String?         @map(\"manual_city\")\n  assignedCourierId     String?         @map(\"assigned_courier_id\") @db.Uuid\n  status                RouteTaskStatus @default(pending)\n  rescheduleDate        DateTime?       @map(\"reschedule_date\") @db.Date\n  failureReason         String?         @map(\"failure_reason\")\n  sortOrder             Int?            @map(\"sort_order\")\n  estimatedArrivalStart DateTime?       @map(\"estimated_arrival_start\") @db.Timestamptz\n  estimatedArrivalEnd   DateTime?       @map(\"estimated_arrival_end\") @db.Timestamptz\n  notes                 String?\n  createdAt             DateTime        @default(now()) @map(\"created_at\") @db.Timestamptz\n  updatedAt             DateTime        @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz\n\n  // Relations\n  trip            Trip           @relation(fields: [tripId], references: [id])\n  parcel          Parcel?        @relation(fields: [parcelId], references: [id])\n  client          Client?        @relation(fields: [clientId], references: [id])\n  address         ClientAddress? @relation(fields: [addressId], references: [id])\n  assignedCourier Profile?       @relation(\"RouteTaskAssignedCourier\", fields: [assignedCourierId], references: [id])\n\n  @@index([tripId])\n  @@index([taskDate])\n  @@index([assignedCourierId])\n  @@index([postalCode])\n  @@map(\"route_tasks\")\n}\n\nmodel WarehouseInventory {\n  id          String          @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  parcelId    String          @map(\"parcel_id\") @db.Uuid\n  placeId     String?         @map(\"place_id\") @db.Uuid\n  action      WarehouseAction\n  scannedById String?         @map(\"scanned_by\") @db.Uuid\n  scannedAt   DateTime        @default(now()) @map(\"scanned_at\") @db.Timestamptz\n  notes       String?\n\n  // Relations\n  parcel    Parcel   @relation(fields: [parcelId], references: [id])\n  scannedBy Profile? @relation(fields: [scannedById], references: [id])\n\n  @@index([parcelId])\n  @@index([scannedAt])\n  @@map(\"warehouse_inventory\")\n}\n\nmodel NpSyncLog {\n  id              String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  parcelId        String?  @map(\"parcel_id\") @db.Uuid\n  action          String\n  requestPayload  Json?    @map(\"request_payload\")\n  responsePayload Json?    @map(\"response_payload\")\n  success         Boolean?\n  errorMessage    String?  @map(\"error_message\")\n  createdAt       DateTime @default(now()) @map(\"created_at\") @db.Timestamptz\n\n  // Relations\n  parcel Parcel? @relation(fields: [parcelId], references: [id])\n\n  @@index([parcelId])\n  @@map(\"np_sync_log\")\n}\n\nmodel YearlySequence {\n  year       Int @id\n  lastNumber Int @default(0) @map(\"last_number\")\n\n  @@map(\"yearly_sequence\")\n}\n\n/**\n * Singleton row holding the carrier's bank requisites + invoice SMS\n * template (per ТЗ — «повідомлення включає наперед заданий шаблон з\n * реквізитами банку надавача послуг»).\n * Template placeholders supported by `renderInvoiceTemplate`:\n * {{name}} — recipient's full name\n * {{amount}} — total cost in EUR (2 decimals)\n * {{itn}} — parcel ITN\n * {{internalNumber}} — internal parcel number\n * {{bankName}}, {{iban}}, {{accountHolder}}, {{swift}} — bank details\n */\nmodel InvoiceSettings {\n  id            String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  /// Marker so we always work with a single row. Always set to TRUE.\n  isSingleton   Boolean  @unique @default(true) @map(\"is_singleton\")\n  bankName      String?  @map(\"bank_name\")\n  iban          String?\n  accountHolder String?  @map(\"account_holder\")\n  swift         String?\n  /// Free-form template; placeholders above are substituted at send time.\n  smsTemplate   String?  @map(\"sms_template\")\n  /// Курс UAH/EUR. Використовується для конвертації оголошеної вартості з\n  /// гривень в євро при розрахунку страхування — інакше 2500 грн дають\n  /// 75 EUR страхування при 3% (бо рахунок ведеться в EUR).\n  uahPerEur     Decimal  @default(42) @map(\"uah_per_eur\") @db.Decimal(8, 2)\n  updatedAt     DateTime @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz\n\n  @@map(\"invoice_settings\")\n}\n\n/**\n * Audit log of every SMS-invoice send attempt — kept regardless of whether\n * the underlying provider succeeded. Lets us answer «коли і кому ми\n * надсилали рахунок» without trusting a remote service log.\n */\nmodel SmsLog {\n  id           String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  parcelId     String?  @map(\"parcel_id\") @db.Uuid\n  toParty      String   @map(\"to_party\") // 'sender' | 'receiver'\n  toPhone      String   @map(\"to_phone\")\n  body         String\n  /// Provider name once we wire one up (e.g. «twilio», «turbosms»). Null\n  /// while we still run the stub-only sender (logs without external call).\n  provider     String?\n  status       String // 'queued' | 'sent' | 'failed'\n  errorMessage String?  @map(\"error_message\")\n  sentById     String?  @map(\"sent_by\") @db.Uuid\n  createdAt    DateTime @default(now()) @map(\"created_at\") @db.Timestamptz\n\n  @@index([parcelId])\n  @@index([createdAt])\n  @@map(\"sms_log\")\n}\n\n/**\n * Per ТЗ §5: «Виклик кур'єра» доступний клієнту лише у країнах/містах,\n * які ми реально обслуговуємо. У EU — будь-яка з обслуговуваних країн.\n * В Україні — лише Львів. Список зберігається тут і конфігурується в\n * адмініструванні (можна додати інші UA-міста коли з'явиться можливість).\n */\nmodel ServiceCity {\n  id                   String        @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  country              Country\n  city                 String\n  /// True = клієнт може обрати «Виклик кур'єра» в цьому місті (per ТЗ).\n  acceptsCourierPickup Boolean       @default(true) @map(\"accepts_courier_pickup\")\n  /// True = у цій країні дозволена «Пошта» (відправка нам поштою) — ТЗ\n  /// docx 14.05.26: опція «Пошта» доступна, лише якщо в Логістиці її\n  /// передбачено для країни. Зберігається по місту, агрегується по країні.\n  acceptsPostal        Boolean       @default(false) @map(\"accepts_postal\")\n  /// ТЗ docx 12.07.26: заборона «Пункт збору» (Відправник) / «Пункт видачі»\n  /// (Отримувач) — механізм аналогічний Пошті та Виклику кур'єра:\n  /// false = опція заборонена для цього міста/країни.\n  acceptsPickupPoint   Boolean       @default(true) @map(\"accepts_pickup_point\")\n  /// ТЗ docx 29.06.26: на кого поширюється обмеження — Відправника, Отримувача\n  /// чи обох. Дозволяє, напр., заборонити «Пошту» лише Відправнику з Австрії,\n  /// лишивши її доступною Отримувачу. both = діє на обидві сторони.\n  target               ServiceTarget @default(both) @map(\"target\")\n  /// ТЗ docx 01.07.26: винятки-міста для правила на ВСЮ країну (city='*').\n  /// Напр. кур'єр заборонений по всій UA, окрім Львова → exceptions=['lviv'].\n  /// Зберігаються нормалізовано (транслітерованими) для узгодженого матчингу.\n  exceptions           String[]      @default([]) @map(\"exceptions\")\n  /// Reserved for future expansion (e.g. delivery service zones).\n  notes                String?\n  createdAt            DateTime      @default(now()) @map(\"created_at\") @db.Timestamptz\n  updatedAt            DateTime      @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz\n\n  @@unique([country, city, target])\n  @@index([country, acceptsCourierPickup])\n  @@map(\"service_cities\")\n}\n\nmodel DescriptionSuggestion {\n  id         String @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  text       String @unique\n  usageCount Int    @default(1) @map(\"usage_count\")\n\n  @@map(\"description_suggestions\")\n}\n\nenum ClaimStatus {\n  open\n  in_progress\n  resolved\n  rejected\n}\n\n/// Immutable record of sensitive operations: deletions, role changes, email\n/// changes, manual cost overrides, etc. Written by logger.audit() callers.\nmodel AuditLog {\n  id          String   @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  event       String // e.g. \"parcel.deleted\", \"user.role_changed\"\n  actorId     String?  @map(\"actor_id\") @db.Uuid\n  subjectId   String?  @map(\"subject_id\") @db.Uuid // the affected entity (parcel, client, user)\n  subjectType String?  @map(\"subject_type\") // \"parcel\" | \"client\" | \"user\" | ...\n  payload     Json? // event-specific metadata\n  createdAt   DateTime @default(now()) @map(\"created_at\") @db.Timestamptz\n\n  @@index([event])\n  @@index([actorId])\n  @@index([subjectId])\n  @@index([createdAt])\n  @@map(\"audit_log\")\n}\n\nmodel Claim {\n  id          String      @id @default(dbgenerated(\"gen_random_uuid()\")) @db.Uuid\n  parcelId    String      @map(\"parcel_id\") @db.Uuid\n  clientId    String?     @map(\"client_id\") @db.Uuid\n  type        String // damage, lost, delay, other\n  description String\n  resolution  String?\n  status      ClaimStatus @default(open)\n  createdById String?     @map(\"created_by\") @db.Uuid\n  createdAt   DateTime    @default(now()) @map(\"created_at\") @db.Timestamptz\n  updatedAt   DateTime    @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz\n\n  parcel    Parcel   @relation(fields: [parcelId], references: [id])\n  client    Client?  @relation(fields: [clientId], references: [id])\n  createdBy Profile? @relation(\"ClaimCreatedBy\", fields: [createdById], references: [id])\n\n  @@index([parcelId])\n  @@index([status])\n  @@map(\"claims\")\n}\n",
